<div class="topline"><span><?= e(t('ONE THING AT A TIME')) ?></span><span><?= e(t('Make space to concentrate.')) ?></span></div><header class="page-header"><div><h1><?= e(t('A little time, well spent.')) ?></h1><p class="muted"><?= e(t('Study in focused blocks. Record the time you actually spend.')) ?></p></div></header><?php require ROOT.'/app/Core/views/notices.php'; ?>
<div class="two-col"><section class="card focus-card"><p class="eyebrow"><?= $active ? e(ucfirst($active['kind'])).' SESSION' : t('READY WHEN YOU ARE') ?></p>
<?php if ($active): $elapsed=FocusService::elapsed($active); ?><h2><?= e($active['subject']) ?></h2><div class="focus-time" data-focus-timer data-status="<?= e($active['status']) ?>" data-total="<?= e($active['target_minutes']*60) ?>" data-elapsed="<?= e($elapsed) ?>" data-rendered="<?= e(time()) ?>"><?= e(sprintf('%02d:%02d',intdiv(max(0,$active['target_minutes']*60-$elapsed),60),max(0,$active['target_minutes']*60-$elapsed)%60)) ?></div><p class="muted" data-focus-state><?= e(ucfirst($active['status'])) ?></p><form action="/focus/<?= e($active['id']) ?>/action" method="post" class="timer-actions"><?= csrf_field() ?><button name="action" value="<?= $active['status']==='running' ? 'pause' : 'resume' ?>"><?= $active['status']==='running' ? t('Pause') : t('Resume') ?></button><button class="secondary" name="action" value="finish"><?= e(t('Finish & save')) ?></button><button class="quiet" name="action" value="cancel"><?= e(t('Cancel')) ?></button></form><p class="footnote"><?= e(t('The timer survives navigation and app restarts. Saved time is capped at the planned duration; finishing early records only elapsed time.')) ?></p>
<?php else: ?><div class="focus-time"><?= e(t('Ready.')) ?></div><p class="muted"><?= e(t('Choose your next study block below.')) ?></p><form class="stack" action="/focus/start" method="post"><?= csrf_field() ?><label><?= e(t('Subject / intention')) ?><input name="subject" maxlength="150" required placeholder="<?= e(t('What will you work on?')) ?>"></label><div class="form-grid"><label><?= e(t('Minutes')) ?><input name="minutes" type="number" min="1" max="120" value="25" required></label><label><?= e(t('Session type')) ?><select name="kind"><option value="study"><?= e(t('Study / focus')) ?></option><option value="break"><?= e(t('Break')) ?></option></select></label></div><label><?= e(t('Link an open task (optional)')) ?><select name="task_id"><option value=""><?= e(t('No task')) ?></option><?php foreach ($tasks as $task): ?><option value="<?= e($task['id']) ?>"><?= e($task['title']) ?></option><?php endforeach; ?></select></label><div class="form-grid"><label><?= e(t('Complete habit after focused minutes')) ?><select name="habit_id"><option value=""><?= e(t('No habit')) ?></option><?php foreach ($habits as $habit): ?><option value="<?= e($habit['id']) ?>"><?= e($habit['title']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Minimum actual minutes')) ?><input name="minimum_minutes" type="number" min="1" max="120" value="25"></label></div><p class="footnote"><?= e(t('Finishing a study session records elapsed time against its task once. Meeting the chosen duration checks the habit once for that date. Breaks and cancelled sessions do not produce events.')) ?></p><button><?= e(t('Start session')) ?></button></form><?php endif; ?></section>
<section class="card"><p class="eyebrow"><?= e(t('TODAY’S COMPLETED STUDY TIME')) ?></p><div class="hero-number"><?= $history ? e($minutes).ui_markup(' <small>minutes</small>') : ui_markup('<span class="no-data">No data yet</span>') ?></div><h3><?= e(t('Your recent sessions')) ?></h3><?php if (!$history): ?><div class="empty"><h3><?= e(t('A first session is a good start.')) ?></h3><p><?= e(t('Your actual study minutes and completed sessions will appear here.')) ?></p></div><?php else: foreach ($history as $session): ?><div class="simple-row"><span><strong><?= e($session['subject']) ?></strong><small><?= e(ucfirst($session['kind'])) ?> · <?= e($session['status']) ?> · <?= e(substr($session['started_at'],0,10)) ?></small></span><span><?= e(number_format(FocusService::elapsed($session)/60,1)) ?> <?= e(t('min')) ?></span></div><?php endforeach; endif; ?></section></div>

<section class="card"><h2><?= e(t('Task time logs')) ?></h2><?php if (!$logs): ?><p class="muted"><?= e(t('Linked completed focus sessions appear here.')) ?></p><?php endif; ?><?php foreach ($logs as $log): ?><div class="simple-row"><span><?= e($log['title']) ?> <?= e(t('· session #')) ?><?= e($log['session_id']) ?></span><span><?= e(round($log['seconds']/60,1)) ?> <?= e(t('min')) ?></span></div><?php endforeach; ?></section>
